#!/bin/bash
sed -i '/Text(if (isConnecting) "ချိတ်ဆက်နေသည်..." else "စမ်းသပ် ချိတ်ဆက်မည်")/a \
                }\n                Spacer(modifier = Modifier.height(8.dp))\n                Button(\n                    onClick = {\n                        kotlinx.coroutines.GlobalScope.launch(kotlinx.coroutines.Dispatchers.Main) {\n                            val textToPrint = "========================\\n      3D VOUCHER\\n========================\\n Test Print Successful\\n========================"\n                            val width = if (paperSize == "80mm") 576 else 384\n                            val bitmap = com.example.logic.BluetoothPrinter.createBitmapFromText(textToPrint, width)\n                            val success = com.example.logic.BluetoothPrinter.printBitmap(bitmap, paperSize)\n                            android.widget.Toast.makeText(context, if (success) "ပရင်ထုတ်ခြင်း အောင်မြင်ပါသည်" else "ပရင်ထုတ်ခြင်း မအောင်မြင်ပါ", android.widget.Toast.LENGTH_SHORT).show()\n                        }\n                    },\n                    modifier = Modifier.fillMaxWidth(),\n                    enabled = macAddress.isNotEmpty()\n                ) {\n                    Text("စမ်းသပ် ပရင်ထုတ်မည်")' app/src/main/java/com/example/ui/SettingsScreen.kt
